<script>$(function(){var t=$('#finance-employee-advance-report'),branch=$('#advance-report-branch'),from=$('#advance-report-from'),to=$('#advance-report-to'),status=$('#advance-report-status'),x=$.fn.dataTable.render.text(),money=$.fn.dataTable.render.number(',','.',2);var dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.branch_scope=branch.val();d.from=from.val();d.to=to.val();d.status=status.val()}},order:[[3,'desc']],buttons:[window.erpExcelButton(t,function(){return{branch_scope:branch.val(),from:from.val(),to:to.val(),status:status.val()}})],columns:[{data:'document_number',name:'a.document_number',render:x.display},{data:'branch_code',name:'b.code',render:x.display},{data:'employee_name',name:'u.name',render:x.display},{data:'date_label',name:'a.document_date',render:x.display},{data:'due_date_label',name:'a.due_date',render:x.display},{data:'status_label',name:'a.status',render:x.display},{data:'amount',name:'a.amount',className:'text-end',render:money},{data:'expense_amount',name:'expense_amount',className:'text-end',render:money},{data:'refund_amount',name:'refund_amount',className:'text-end',render:money},{data:'additional_amount',name:'additional_amount',className:'text-end',render:money},{data:'outstanding_amount',name:'outstanding_amount',className:'text-end',render:money},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,type,row){return type==='display'?'<a class="btn btn-sm btn-app-soft" href="'+x.display(row.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-show" aria-hidden="true"></i></a>':'';}}]}));branch.add(from).add(to).add(status).on('change',function(){dt.ajax.reload()});$('#advance-report-reset').on('click',function(){branch.val('current');from.val('');to.val('');status.val('');dt.ajax.reload()});});</script>
